def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal separator: encode non-background cells in the lower panel.
    for r in range(h):
        if len(set(grid[r])) == 1:
            sep = grid[r][0]
            if sep == 7:
                return [[3 if v != 5 else 5 for v in row] for row in grid[r + 1:]]

    # Vertical separator: find a constant column and take the panel after it.
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            sep = grid[0][c]
            if sep == 5:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                return [
                    [3 if v != 1 and left[r][j] != 4 else 1 for j, v in enumerate(row)]
                    for r, row in enumerate(right)
                ]
            if sep == 9:
                right = [row[c + 1:] for row in grid]
                bg = max(set(v for row in right for v in row),
                         key=lambda x: sum(row.count(x) for row in right))
                return [[3 if v != bg else bg for v in row] for row in right]

    return grid
