def transform(grid):
    h, w = len(grid), len(grid[0])

    # Vertical separator. The sparse right-hand pattern is printed as 3s,
    # with marks suppressed wherever the aligned left panel contains a 4.
    for c in range(w):
        if all(row[c] == grid[0][c] for row in grid):
            sep = grid[0][c]
            if sep == 5:
                left = [row[:c] for row in grid]
                right = [row[c + 1:] for row in grid]
                out = []
                for r, row in enumerate(right):
                    out.append([
                        3 if value != 1 and (j >= len(left[r]) or left[r][j] != 4) else 1
                        for j, value in enumerate(row)
                    ])
                return out

            if sep == 9:
                left = [row[:c] for row in grid]
                bg = max(set(v for row in left for v in row),
                         key=lambda v: sum(row.count(v) for row in left))
                return [[3 if v != bg else 8 for v in row] for row in left]

    # Horizontal divider example: combine the two binary panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] == 7:
            upper, lower = grid[:r], grid[r + 1:]
            out = []
            for a, b in zip(upper, lower):
                out.append([3 if (x == 0) != (y == 2) else 5
                            for x, y in zip(a, b)])
            return out

    return grid
